<?php
declare(strict_types=1);
require __DIR__ . '/shared_town_service_test.php';

$second=auth_register($pdo,'position_test_b','secret1','position-b','127.0.0.2',static fn()=>$now)['user']['id'];
$third=auth_register($pdo,'position_test_c','secret1','position-c','127.0.0.3',static fn()=>$now)['user']['id'];
$first=shared_town_player_position($pdo,$second,$now,static fn()=>600);
town_shared_expect($first['tile_x']===600 && $first['tile_y']===600,'New players can spawn in the expanded part of the map.');
$again=shared_town_player_position($pdo,$second,$now->modify('+1 day'),static function(){throw new RuntimeException('Returning player must not randomize again.');});
town_shared_expect($again===$first,'Returning players restore their initial position across sessions.');
$other=shared_town_player_position($pdo,$third,$now,static fn()=>40);
town_shared_expect($other['tile_x']===40 && $other!==$first,'First-entry random selection is separate for each account.');
$px=600*16+8.25; $py=601*16+15.5;
shared_town_presence_upsert($pdo,$second,['tile_x'=>600,'tile_y'=>601,'pixel_x'=>$px,'pixel_y'=>$py],$now);
$validated=shared_town_presence_upsert($pdo,$second,['tile_x'=>601,'tile_y'=>601,'pixel_x'=>$px+16,'pixel_y'=>$py],$now,false);
town_shared_expect($validated['pixel_x']===$px+16 && $validated['pixel_y']===$py,'Transient presence returns validated sub-tile coordinates.');
town_shared_expect(shared_town_player_position($pdo,$second,$now)['pixel_x']===$px,'Transient presence does not write the durable position.');
$online=shared_town_presence($pdo,-1,-1,$now)['presence'];
$self=array_values(array_filter($online,static fn($row)=>$row['user_id']===$second))[0];
town_shared_expect($self['pixel_x']===$px && $self['pixel_y']===$py,'HTTP snapshots retain saved pixel precision for reconnect recovery.');
town_shared_error('invalid_position',400,static fn()=>shared_town_presence_upsert($pdo,$second,['tile_x'=>64,'tile_y'=>20],$now,false));
shared_town_presence($pdo,-1,-1,$now->modify('+1 hour'));
$restored=shared_town_player_position($pdo,$second,$now->modify('+1 hour'));
town_shared_expect($restored['pixel_x']===$px && $restored['pixel_y']===$py,'Expired online presence does not erase the last pixel position.');
town_shared_expect(shared_town_player_position($pdo,$third,$now)===$other,'Movement never overwrites another account position.');
town_shared_expect(shared_town_world($pdo)['chunk_columns']===32 && shared_town_world($pdo)['chunk_rows']===32,'The expanded map has 32 by 32 chunks.');
town_shared_expect(shared_town_parse_chunks('31:31,16:24')===[[31,31],[16,24]],'New edge chunks are accepted.');
town_shared_expect(shared_town_chunk($pdo,31,31)['chunk_x']===31,'Edge chunk loads successfully.');
town_shared_error('invalid_chunks',400,static fn()=>shared_town_parse_chunks('32:0'));
town_shared_error('invalid_position',400,static fn()=>shared_town_presence_upsert($pdo,$second,['tile_x'=>768,'tile_y'=>601],$now));
town_shared_error('invalid_position',400,static fn()=>shared_town_presence_upsert($pdo,$second,['tile_x'=>64,'tile_y'=>20],$now));
town_shared_error('invalid_position',400,static fn()=>shared_town_presence_upsert($pdo,$second,['tile_x'=>600,'tile_y'=>601,'pixel_x'=>100,'pixel_y'=>$py],$now));
town_shared_expect(shared_town_player_position($pdo,$second,$now)===$restored,'Invalid movement cannot replace a saved position.');
shared_town_action($pdo,$user,['action'=>'place','operation_id'=>'block-saved-player-location','asset_id'=>$townAssetId,'tile_x'=>600,'tile_y'=>601],$now);
$relocated=shared_town_player_position($pdo,$second,$now);
town_shared_expect(abs($relocated['tile_x']-600)+abs($relocated['tile_y']-601)===1,'A blocked saved position moves to a neighboring safe tile.');
town_shared_expect(shared_town_player_position($pdo,$second,$now)===$relocated,'The corrected safe position is persisted.');
town_shared_expect(!shared_town_player_can_stand(62*16+8,20*16+15,[]),'River banks match client collision rules.');
town_shared_expect(shared_town_player_can_stand(767*16+8,767*16+15,[]),'The far expanded corner is walkable.');
echo "town_player_positions_test: {$checks} checks ok\n";
